package com.hbm.machine.reactor.pile.core;
import com.hbm.api.tool.ToolableBlock;import com.mojang.serialization.MapCodec;import java.util.List;import net.minecraft.core.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.level.storage.loot.LootParams;
public final class PileBodyBlock extends BaseEntityBlock implements ToolableBlock {
 public static final int META_DUMMY=0,META_CORE=1,META_CHANNEL=2,META_FUEL_IN=3,META_FUEL_OUT=4,META_AIR_IN=5,META_AIR_OUT=6,META_CONTROL=7,META_EDGE=8;
 private static final ThreadLocal<Boolean> RESTORING=ThreadLocal.withInitial(()->false);
 public PileBodyBlock(){super(Properties.of().mapColor(MapColor.METAL).strength(15,6).sound(SoundType.METAL).requiresCorrectToolForDrops());registerDefaultState(stateDefinition.any().setValue(PileCoreContent.META,0));}
 @Override protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> builder){builder.add(PileCoreContent.META);}@Override protected RenderShape getRenderShape(BlockState state){return RenderShape.MODEL;}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return state.getValue(PileCoreContent.META)==META_CORE?new TileEntityPileCore(pos,state):new TileEntityPileBaseMK2(pos,state);}
 @Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){if(state.getValue(PileCoreContent.META)==META_CORE)return createTickerHelper(type,PileCoreContent.CORE.get(),PileTickingBlockEntity::tick);return createTickerHelper(type,PileCoreContent.PART.get(),PileTickingBlockEntity::tick);}
 @Override protected List<ItemStack> getDrops(BlockState state,LootParams.Builder context){return List.of();}
 @Override protected void onRemove(BlockState state,Level level,BlockPos pos,BlockState next,boolean moving){if(!next.is(this)&&!level.isClientSide){var tile=level.getBlockEntity(pos);if(tile instanceof TileEntityPileCore core)core.ejectAll();if(!RESTORING.get()&&!TileEntityPileCore.meltingDown){if(tile instanceof TileEntityPileBaseMK2 part)restore(level,pos,part);else restore(level,pos,null);}}super.onRemove(state,level,pos,next,moving);}
 static void restore(Level level,BlockPos pos,TileEntityPileBaseMK2 part){if(RESTORING.get())return;RESTORING.set(true);try{if(part==null||part.coreY!=-999){level.removeBlockEntity(pos);level.setBlockAndUpdate(pos,PileCoreContent.BRICK.get().defaultBlockState());}if(part!=null){var core=part.getCore();if(core!=null&&!core.isInvalid())core.destroy();}}finally{RESTORING.remove();}}
 @Override public boolean onScrew(Level level,Player player,BlockPos pos,Direction side,float hx,float hy,float hz,ToolType tool){if(tool!=ToolType.HAND_DRILL)return false;var tile=level.getBlockEntity(pos);if(tile instanceof TileEntityPileCore||level.getBlockState(pos).getValue(PileCoreContent.META)==META_CORE){PileErrors.send(level,pos.getX(),pos.getY(),pos.getZ(),"core",player);return false;}if(tile instanceof TileEntityPileBaseMK2 part){if(level.isClientSide)return true;var core=part.getCore();if(core!=null)return core.drillChannel(pos.getX(),pos.getY(),pos.getZ(),PileDirection.of(side.getOpposite()),player);}PileErrors.send(level,pos.getX(),pos.getY(),pos.getZ(),"no_core",player);return false;}
}
